import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/tmp/app.db'
SECRET = os.environ.get('APP_SECRET', 'dev-secret-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, email TEXT, role TEXT, api_key TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, title TEXT, content TEXT, owner_id INTEGER, classification TEXT)')
    db.execute("INSERT OR IGNORE INTO users VALUES (1, 'admin', 'admin@corp.io', 'admin', 'sk-admin-9f8e7d6c5b4a')")
    db.execute("INSERT OR IGNORE INTO users VALUES (2, 'analyst', 'analyst@corp.io', 'user', 'sk-user-1a2b3c4d5e6f')")
    db.execute("INSERT OR IGNORE INTO documents VALUES (1, 'Q4 Revenue', 'Revenue: $4.2M', 1, 'confidential')")
    db.execute("INSERT OR IGNORE INTO documents VALUES (2, 'Public Roadmap', 'Next release: v3.0', 2, 'public')")
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Key')
        if not token:
            return jsonify({'error': 'Missing API key'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key = ?', (token,)).fetchone()
        if not user:
            return jsonify({'error': 'Invalid API key'}), 403
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def audit_log(action, details):
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    entry = f"[{timestamp}] action={action} user={g.get('current_user', {}).get('username', 'anon')} details={details}"
    app.logger.info(entry)

@app.route('/api/documents', methods=['GET'])
@require_auth
def search_documents():
    query = request.args.get('q', '')
    classification = request.args.get('classification', '')
    page = request.args.get('page', '1')

    # Input length validation
    if len(query) > 200 or len(classification) > 50:
        return jsonify({'error': 'Input too long'}), 400

    # Build base query with parameterized search
    sql = "SELECT id, title, classification FROM documents WHERE title LIKE ?"
    params = [f'%{query}%']

    # Classification filter - uses whitelist validation
    valid_classifications = ['public', 'internal', 'confidential', 'secret']
    if classification and classification in valid_classifications:
        sql += " AND classification = ?"
        params.append(classification)

    # Pagination - validated as integer
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 20
    sql += f" LIMIT 20 OFFSET {offset}"

    # Role-based access control filter
    if g.current_user['role'] != 'admin':
        sql += " AND (classification = 'public' OR owner_id = ?)"
        params.append(g.current_user['id'])

    audit_log('search', f'q={query} classification={classification}')

    db = get_db()
    results = db.execute(sql, params).fetchall()
    return jsonify({'documents': [dict(r) for r in results]})

@app.route('/api/documents/<int:doc_id>/export', methods=['GET'])
@require_auth
def export_document(doc_id):
    fmt = request.args.get('format', 'json')
    callback = request.args.get('callback', '')

    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()

    if not doc:
        return jsonify({'error': 'Not found'}), 404

    # Access control check
    if g.current_user['role'] != 'admin':
        if dict(doc)['classification'] != 'public' and dict(doc)['owner_id'] != g.current_user['id']:
            return jsonify({'error': 'Access denied'}), 403

    doc_dict = dict(doc)

    if fmt == 'jsonp' and callback:
        # JSONP support for legacy dashboard widgets
        import json
        response_body = f"{callback}({json.dumps(doc_dict)})"
        resp = app.response_class(response=response_body, mimetype='application/javascript')
        return resp

    return jsonify(doc_dict)

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
